from abc import ABCMeta, abstractmethod
import six
import codecs
from ute_admin_infomodel.protobuf.objectid import decode_object_id

integer = six.integer_types[-1]


class ProtobufTypeId(object):

    VARINT = 0
    FIXED_64 = 1
    LENGTH_DELIMITED = 2
    FIXED_32 = 5


class IdleValueModifier(object):

    def apply(self, value):
        """Apply parameter value modifications."""
        return value

    def revert(self, value):
        """Revert parameter value modifications."""
        return value


class ParameterDefinitionBase(object):

    __metaclass__ = ABCMeta

    simple_types = {
        "string": (codecs.decode if six.PY3 else str, str),
        "float": (float, float),
        "double": (float, float),
        "boolean": (bool, int),
        "ObjectId": (decode_object_id, str),
        "integer": (integer, integer),
    }

    def __init__(self, element):
        self.enum = {}
        self.name = self._get_name(element)
        self.type_name = self._get_type_name(element)
        self.range = self._get_range(element)
        self.value_modifier = self._get_value_modifier(element)

    @abstractmethod
    def is_array(self):
        """Check if defintion is array."""

    @abstractmethod
    def is_simple(self):
        """Check if defintion is simple."""

    @abstractmethod
    def is_enum(self):
        """Check if defintion is enum."""

    @abstractmethod
    def is_complex(self):
        """Check if defintion is comlex."""

    @abstractmethod
    def get_type_definition(self):
        """Get parameter type definition"""

    def get_internal_type(self):
        """Get parameter type used in InfoModel tree."""
        return self._get_simple_type()[0]

    def get_protobuf_type(self):
        """Get parameter type used for protobuf encoding."""
        return self._get_simple_type()[1]

    def _get_simple_type(self):
        return self.simple_types[self.type_name]

    @abstractmethod
    def _get_name(self, element):
        """Get param name."""

    @abstractmethod
    def _get_type_name(self, element):
        """Get type name."""

    def _get_range(self, element):
        return (None, None)

    def _get_value_modifier(self, element):
        return IdleValueModifier()


class ParameterContainerBase(object):

    __metaclass__ = ABCMeta

    @abstractmethod
    def iter_parameters(self):
        """Iterate over internal parameters."""
